// ==UserScript==
// @name         TW Mail Autocomplete (PlemionaPlaner)
// @version      2.4
// @description  Auto-fills the recipient, subject and message on the Tribal Wars mail compose page from URL hash params generated by PlemionaPlaner.
// @match        https://*.plemiona.pl/game.php*
// @match        http://*.plemiona.pl/game.php*
// @grant        none
// @run-at       document-start
// ==/UserScript==

(function () {
    'use strict';

    // Read hash NOW – before TW's own scripts can clear/overwrite window.location.hash
    const rawHash = window.location.hash.substr(1);
    if (!rawHash) return;

    const params = {};
    rawHash.split('&').forEach(function (item) {
        const eq = item.indexOf('=');
        if (eq === -1) return;
        try {
            params[decodeURIComponent(item.slice(0, eq))] = decodeURIComponent(item.slice(eq + 1));
        } catch (e) { /* malformed encoding – skip */ }
    });

    if (!params.to && !params.subject && !params.message) return;

    // Set a field value and fire events so TW's JS framework picks up the change
    function setField(el, value) {
        // Use native setter to bypass any framework wrapping (React, etc.)
        const nativeSetter = Object.getOwnPropertyDescriptor(
            el.tagName === 'TEXTAREA' ? window.HTMLTextAreaElement.prototype : window.HTMLInputElement.prototype,
            'value'
        );
        if (nativeSetter && nativeSetter.set) {
            nativeSetter.set.call(el, value);
        } else {
            el.value = value;
        }
        el.dispatchEvent(new Event('input',  { bubbles: true }));
        el.dispatchEvent(new Event('change', { bubbles: true }));
    }

    function getFields() {
        return {
            to:      document.getElementById('to'),
            subject: document.getElementsByName('subject')[0] || null,
            message: document.getElementById('message'),
        };
    }

    function fillAll() {
        const f = getFields();
        let filled = 0;
        if (params.to      && f.to)      { setField(f.to,      params.to);      filled++; }
        if (params.subject && f.subject)  { setField(f.subject, params.subject); filled++; }
        if (params.message && f.message)  { setField(f.message, params.message); filled++; }
        return filled;
    }

    var needed = (params.to ? 1 : 0) + (params.subject ? 1 : 0) + (params.message ? 1 : 0);

    // Poll every 50 ms until all fields appear, then fill and watch for overwrites
    var attempts = 0;
    var interval = setInterval(function () {
        const f = getFields();
        const ready = (params.to ? !!f.to : true) && (params.subject ? !!f.subject : true) && (params.message ? !!f.message : true);
        if (ready || ++attempts > 200) {
            clearInterval(interval);
            if (!ready) return;

            fillAll();

            // Watch for TW overwriting our values and re-fill once
            var refilled = false;
            var observer = new MutationObserver(function () {
                if (refilled) { observer.disconnect(); return; }
                const f2 = getFields();
                const lost = (params.to && f2.to && !f2.to.value) ||
                             (params.subject && f2.subject && !f2.subject.value) ||
                             (params.message && f2.message && !f2.message.value);
                if (lost) { refilled = true; fillAll(); observer.disconnect(); }
            });
            observer.observe(document.body, { subtree: true, attributes: true, childList: true, characterData: true });
            // Stop watching after 5 s
            setTimeout(function () { observer.disconnect(); }, 5000);
        }
    }, 50);
})();
